    const dim = vector.length;
    const providerUsed = fallbackUsed ? 'hash' : normalizeProvider(cfg.embeddingProvider);
    const modelUsed = (fallbackUsed || providerUsed === 'hash') ? `hash-${dim || cfg.hashDimensions}` : (cfg.embeddingModel || '');
